import Foundation

/// Вирішує, що НЕ можна класти в історію буфера: паролі, приховані типи, ключі.
public enum PasteboardPolicy {
    /// Типи, якими програми позначають секретний або тимчасовий вміст (nspasteboard.org).
    public static let concealedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "com.agilebits.onepassword.otp",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
    ]

    /// Менеджери паролів: усе, що скопійовано з них, пропускаємо.
    public static let passwordManagerApps: Set<String> = [
        "com.apple.keychainaccess",
        "com.apple.Passwords",
        "com.bitwarden.desktop",
        "com.lastpass.LastPass",
        "com.dashlane.dashlanephonefinal",
        "com.dashlane.Dashlane",
        "org.keepassxc.keepassxc",
        "com.enpass.Enpass-Desktop",
        "in.sinew.Enpass-Desktop",
        "com.nordpass.macos.NordPass",
        "com.keepersecurity.passwordmanager",
        "com.proton.pass.electron",
    ]

    /// Префікси ідентифікаторів 1Password (у різних версій вони різні).
    public static let passwordManagerPrefixes = ["com.1password.", "com.agilebits."]

    /// Тип, у який деякі програми кладуть ідентифікатор програми-джерела.
    public static let sourceType = "org.nspasteboard.source"

    public static func isPasswordManager(_ bundleID: String?) -> Bool {
        guard let id = bundleID else { return false }
        if passwordManagerApps.contains(id) { return true }
        return passwordManagerPrefixes.contains { id.hasPrefix($0) }
    }

    /// true — пропустити вміст, навіть не читаючи сам текст.
    public static func shouldSkip(types: [String], sourceBundleID: String?) -> Bool {
        if types.contains(where: concealedTypes.contains) { return true }
        return isPasswordManager(sourceBundleID)
    }

    /// Чи схожий текст на ключ/токен/пароль (щоб випадково не зберегти ключ API).
    /// Перевіряє і весь текст, і кожне «слово» в ньому — ключ часто стоїть у рядку `KEY=sk-…` чи `Bearer …`.
    public static func looksLikeSecret(_ text: String) -> Bool {
        let t = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !t.isEmpty else { return false }
        if t.contains("-----BEGIN") && t.contains("PRIVATE KEY") { return true }
        // Токен Telegram-бота: 123456789:AA…(35 символів).
        if t.range(of: #"\b\d{8,10}:[A-Za-z0-9_-]{35}\b"#, options: .regularExpression) != nil { return true }
        // Посилання цілком (до розбиття по «:») — не секрет, навіть з довгими параметрами.
        if t.range(of: #"^https?://\S+$"#, options: .regularExpression) != nil { return false }
        let separators = CharacterSet.whitespacesAndNewlines.union(CharacterSet(charactersIn: "=:\"'`,;()[]{}<>"))
        let pieces = t.components(separatedBy: separators).filter { !$0.isEmpty }
        return pieces.contains(where: isTokenLike)
    }

    private static let knownPrefixes = ["sk-ant-", "sk-proj-", "sk-", "ghp_", "gho_", "ghs_", "github_pat_",
                                        "glpat-", "xoxb-", "xoxp-", "AKIA", "AIza", "eyJ"]

    private static func isTokenLike(_ t: String) -> Bool {
        if t.count >= 20, knownPrefixes.contains(where: { t.hasPrefix($0) }) { return true }
        guard t.count >= 32 else { return false }
        // Шляхи й посилання («Documents/Report…», «a/b/c») — не секрети.
        if t.range(of: #"[A-Za-z]/[A-Za-z]"#, options: .regularExpression) != nil || t.contains("://") { return false }
        // Довгий набір латинських літер і цифр без пробілів (наприклад, токен монобанку).
        let tokenChars = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "-_+/="))
        let isTokenChars = t.unicodeScalars.allSatisfy { tokenChars.contains($0) && $0.isASCII }
        let hasDigit = t.rangeOfCharacter(from: .decimalDigits) != nil
        let hasUpper = t.rangeOfCharacter(from: .uppercaseLetters) != nil
        let hasLower = t.rangeOfCharacter(from: .lowercaseLetters) != nil
        return isTokenChars && hasDigit && hasUpper && hasLower
    }
}
